  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
    terms: 'NET14',
  });

  assert.equal(inv.ok, true);
  let withVoucher = applyVoucher(inv.value, { code: 'SAVE10', amount: 10000 }).value;
  let issued = issueInvoice(withVoucher, []).value;
  const totals = invoiceTotals(issued);
  const paymentAmount = Math.floor(totals.total / 2);

  issued = recordPayment(issued, {
    amount: paymentAmount,
    date: '2025-10-10',
  }).value;

  const text = renderInvoiceText(issued);

  assert(text.includes('INV-2025-0001'));
  assert(text.includes('Blue Fern Bakery'));
  assert(text.includes('LOGO-PACK'));
  assert(text.includes('Voucher: -€100.00'));
  assert(text.includes('Total:'));
  assert(text.includes('Due: 2025-10-21'));
  assert(text.includes('Paid:'));
});

test('renderInvoiceText voucher before total', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  assert.equal(inv.ok, true);
  const withVoucher = applyVoucher(inv.value, { code: 'SAVE10', amount: 10000 }).value;
  const text = renderInvoiceText(withVoucher);

  const lines = text.split('\n');
  const voucherIndex = lines.findIndex(line => line.startsWith('Voucher:'));
  const totalIndex = lines.findIndex(line => line.startsWith('Total:'));

  assert(voucherIndex >= 0, 'Voucher line should exist');
  assert(totalIndex >= 0, 'Total line should exist');
  assert(voucherIndex < totalIndex, 'Voucher should come before Total');
});
